  $content .= $buf;
}
close($fh);

# Search for patterns that might be passwords: 23 bytes where certain positions match constraints
# Position 0-2 should decode to "8XD"
# Position 20-22 should decode to "W54"
# All 23 bytes should decode to [A-Z0-9]

my %results = ();

# For each of the two W54 locations, try all possible XOR keys
my @w54_offsets = (259938, 3145737);
for my $w54_pos (@w54_offsets) {
  my $pwd_start = $w54_pos - 20;
  my $pwd = substr($content, $pwd_start, 23);

  # For this 23-byte sequence, we know:
  # - When XORed with some key, bytes 0-2 become 0x38,0x58,0x44 (8XD)
  # - When XORed with some key, bytes 20-22 become 0x57,0x35,0x34 (W54)
  # - When XORed with some key, all other bytes become [A-Z0-9]

  my $byte0 = ord(substr($pwd, 0, 1));
  my $byte1 = ord(substr($pwd, 1, 1));
  my $byte2 = ord(substr($pwd, 2, 1));
  my $byte20 = ord(substr($pwd, 20, 1));
  my $byte21 = ord(substr($pwd, 21, 1));
  my $byte22 = ord(substr($pwd, 22, 1));

  # Deduce XOR key from first 3 bytes
  my $key_from_first = $byte0 ^ 0x38;  # 8
  my $key_from_last = $byte20 ^ 0x57;  # W

  print "Position $pwd_start:\n";
  print "  Deduced key from byte 0 (0x$byte0 -> 8): 0x" . sprintf("%02X", $key_from_first) . "\n";
  print "  Deduced key from byte 20 (0x$byte20 -> W): 0x" . sprintf("%02X", $key_from_last) . "\n";

  # Check if first byte deduced key also works for bytes 1,2
  if (($byte1 ^ $key_from_first) == 0x58 && ($byte2 ^ $key_from_first) == 0x44) {
    print "  Key 0x" . sprintf("%02X", $key_from_first) . " matches first 3 bytes!\n";
    if (($byte20 ^ $key_from_first) == 0x57 && ($byte21 ^ $key_from_first) == 0x35 && ($byte22 ^ $key_from_first) == 0x34) {
      print "  Key 0x" . sprintf("%02X", $key_from_first) . " also matches last 3 bytes!\n";
      my $decoded = "";
      my $valid = 1;
      for my $i (0..22) {
        my $byte = ord(substr($pwd, $i, 1)) ^ $key_from_first;
        if (($byte >= 65 && $byte <= 90) || ($byte >= 48 && $byte <= 57)) {
          $decoded .= chr($byte);
        } else {
          $valid = 0;
          print "    Byte $i decodes to 0x" . sprintf("%02X", $byte) . " - invalid\n";
          last;
        }
      }
      if ($valid) {
        print "  VALID PASSWORD: $decoded\n";
        $results{$decoded} = $pwd_start;
      }
    }
  }

  # Also check key from last bytes
  if (($byte20 ^ $key_from_last) == 0x57 && ($byte21 ^ $key_from_last) == 0x35 && ($byte22 ^ $key_from_last) == 0x34) {
    print "  Key 0x" . sprintf("%02X", $key_from_last) . " matches last 3 bytes!\n";
    if (($byte0 ^ $key_from_last) == 0x38 && ($byte1 ^ $key_from_last) == 0x58 && ($byte2 ^ $key_from_last) == 0x44) {
      print "  Key 0x" . sprintf("%02X", $key_from_last) . " also matches first 3 bytes!\n";
      my $decoded = "";
      my $valid = 1;
      for my $i (0..22) {
        my $byte = ord(substr($pwd, $i, 1)) ^ $key_from_last;
        if (($byte >= 65 && $byte <= 90) || ($byte >= 48 && $byte <= 57)) {
          $decoded .= chr($byte);
        } else {
          $valid = 0;
          last;
        }
      }
      if ($valid) {
        print "  VALID PASSWORD: $decoded\n";
        $results{$decoded} = $pwd_start;
      }
    }
  }
  print "\n";
}

